@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500&family=Playfair+Display:ital,wght@0,400;0,600;1,400&display=swap');

:root {
  --bg-color: #F5F2ED;
  --text-color: #1A1A1A;
  --accent-color: #C08A72; /* warm terracotta accent */
  --accent-alt: #9A9E82; /* sage accent */
  --accent-sand: #D5C2A4; /* sand accent */
  --font-serif: 'Playfair Display', serif;
  --font-sans: 'Inter', sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-color);
  color: var(--text-color);
  font-family: var(--font-sans);
  line-height: 1.6;
  font-size: 18px;
  font-weight: 300;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 400;
  line-height: 1.2;
}

a {
  color: var(--text-color);
  text-decoration: none;
  transition: opacity 0.3s ease;
}

a:hover {
  opacity: 0.6;
}

/* Header & Nav */
header {
  padding: 40px 6vw;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
  z-index: 100;
}

.logo {
  font-family: var(--font-serif);
  font-size: 24px;
  font-weight: 600;
}

.desktop-nav {
  display: flex;
  gap: 40px;
}

.desktop-nav a {
  font-size: 16px;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.mobile-toggle {
  display: none;
  cursor: pointer;
  z-index: 200;
  background: none;
  border: none;
  width: 30px;
  height: 20px;
  position: relative;
}

.mobile-toggle span {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--text-color);
  position: absolute;
  transition: all 0.3s ease;
}

.mobile-toggle span:first-child {
  top: 0;
}
.mobile-toggle span:nth-child(2) {
  top: 9px;
}
.mobile-toggle span:last-child {
  top: 18px;
}

.mobile-toggle.active span:first-child {
  transform: rotate(45deg);
  top: 9px;
}
.mobile-toggle.active span:nth-child(2) {
  opacity: 0;
}
.mobile-toggle.active span:last-child {
  transform: rotate(-45deg);
  top: 9px;
}

.mobile-menu {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100vh;
  background-color: var(--bg-color);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 150;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.4s ease;
}

.mobile-menu.active {
  opacity: 1;
  pointer-events: auto;
}

.mobile-menu a {
  font-family: var(--font-serif);
  font-size: 10vw;
  margin: 10px 0;
}

@media (max-width: 768px) {
  .desktop-nav {
    display: none;
  }
  .mobile-toggle {
    display: block;
  }
}

/* Layout Blocks */
.container {
  padding: 0 6vw 100px;
  max-width: 1600px;
  margin: 0 auto;
}

/* Hero Section */
.hero {
  padding: 80px 0;
  max-width: 1200px;
}

.hero h1 {
  font-size: clamp(3rem, 6vw, 6rem);
  letter-spacing: -0.02em;
}

/* Media Showcase */
.media-showcase {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 2vw;
  margin: 60px 0;
}

.media-block {
  aspect-ratio: 4/5;
  background-color: var(--accent-color);
}
.media-block:nth-child(2) {
  background-color: var(--accent-alt);
  transform: translateY(40px);
}
.media-block:nth-child(3) {
  background-color: var(--accent-sand);
}

@media (max-width: 768px) {
  .media-showcase {
    grid-template-columns: 1fr;
  }
  .media-block:nth-child(2) {
    transform: translateY(0);
  }
}

/* Client Marquee */
.marquee-container {
  overflow: hidden;
  padding: 60px 0;
  border-top: 1px solid rgba(26,26,26,0.1);
  border-bottom: 1px solid rgba(26,26,26,0.1);
  margin-bottom: 100px;
}

.marquee-row {
  display: flex;
  white-space: nowrap;
  font-family: var(--font-sans);
  font-size: 2rem;
  font-weight: 400;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.marquee-row:last-child {
  margin-bottom: 0;
}

.marquee-content {
  display: flex;
  animation: scroll-left 40s linear infinite;
}

.marquee-content.reverse {
  animation: scroll-right 40s linear infinite;
}

.marquee-item {
  padding: 0 20px;
}
.marquee-item::after {
  content: "◦";
  margin-left: 40px;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* Typography elements */
.section-heading {
  font-family: var(--font-sans);
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 40px;
  color: rgba(26,26,26,0.5);
}

.text-content {
  max-width: 800px;
  margin-left: auto;
}

.text-content p {
  font-size: 24px;
  margin-bottom: 30px;
  line-height: 1.5;
}

@media (max-width: 768px) {
  .text-content {
    margin-left: 0;
  }
  .text-content p {
    font-size: 18px;
  }
}

/* Founder Letter (neweno.html) */
.editorial-content {
  max-width: 700px;
  margin: 0 auto;
  padding: 60px 0 120px;
}

.editorial-content h1 {
  font-size: clamp(2.5rem, 5vw, 4.5rem);
  margin-bottom: 60px;
}

.editorial-content p {
  font-size: 20px;
  margin-bottom: 30px;
  line-height: 1.7;
}

/* Services */
.philosophy {
  max-width: 1000px;
  margin-bottom: 120px;
}
.philosophy h2 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  margin-bottom: 40px;
}

.service-item {
  border-top: 1px solid rgba(26,26,26,0.1);
  padding: 60px 0;
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 40px;
}

.service-item h3 {
  font-size: 32px;
}

.service-item p {
  font-size: 20px;
}

@media (max-width: 768px) {
  .service-item {
    grid-template-columns: 1fr;
    gap: 20px;
    padding: 40px 0;
  }
}

/* Clients Grid */
.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 60px 40px;
  padding-top: 60px;
}

.client-item {
  border-top: 1px solid rgba(26,26,26,0.1);
  padding-top: 20px;
}

.client-item h3 {
  font-family: var(--font-sans);
  font-size: 24px;
  font-weight: 500;
  margin-bottom: 15px;
}

.client-item p {
  font-size: 16px;
  color: rgba(26,26,26,0.8);
}

@media (max-width: 1024px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .clients-grid {
    grid-template-columns: 1fr;
  }
}

/* Contact */
.contact-wrapper {
  height: calc(100vh - 100px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
}

.contact-wrapper h1 {
  font-size: clamp(4rem, 15vw, 12rem);
  margin-bottom: 60px;
  line-height: 0.9;
}

.contact-links {
  display: flex;
  gap: 40px;
}

.contact-links a {
  font-family: var(--font-sans);
  font-size: 24px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  position: relative;
}

.contact-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 100%;
  height: 1px;
  background-color: var(--text-color);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.4s ease;
}

.contact-links a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

@media (max-width: 600px) {
  .contact-links {
    flex-direction: column;
    gap: 20px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const mobileToggle = document.querySelector('.mobile-toggle');
  const mobileMenu = document.querySelector('.mobile-menu');

  if (mobileToggle && mobileMenu) {
    mobileToggle.addEventListener('click', () => {
      mobileToggle.classList.toggle('active');
      mobileMenu.classList.toggle('active');
    });
  }

  // Duplicate marquee content for seamless scrolling
  const marquees = document.querySelectorAll('.marquee-content');
  marquees.forEach(marquee => {
    const children = Array.from(marquee.children);
    children.forEach(child => {
      const clone = child.cloneNode(true);
      marquee.appendChild(clone);
    });
  });
});

